SELECT data_rows.id, data_rows.should_delete, data_rows.conversation_id, data_rows.turn_id, data_rows.message_id, data_rows.provider, data_rows.mode, data_rows.copy_mode, data_rows.status, data_rows.payload_id, data_rows.container_id, data_rows.provider_file_id, data_rows.filename, data_rows.mime_type, data_rows.size_bytes, data_rows.checksum, data_rows.error_message, data_rows.expires_at, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `id`, `conversation_id`, `turn_id`, `message_id`, `provider`, `mode`, `copy_mode`, `status`, `payload_id`, `container_id`, `provider_file_id`, `filename`, `mime_type`, `size_bytes`, `checksum`, `error_message`, `expires_at`, `created_at`, `updated_at` FROM generated_file)  data_rows